--
-- Triggers `lots`
--
DELIMITER $$
CREATE TRIGGER `tr_lots_after_delete` AFTER DELETE ON `lots` FOR EACH ROW BEGIN
    UPDATE projects 
    SET total_lots = total_lots - 1,
        available_lots = CASE 
            WHEN OLD.status = 'available' THEN available_lots - 1 
            ELSE available_lots 
        END
    WHERE id = OLD.project_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_lots_after_insert` AFTER INSERT ON `lots` FOR EACH ROW BEGIN
    UPDATE projects 
    SET total_lots = total_lots + 1,
        available_lots = available_lots + 1
    WHERE id = NEW.project_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_lots_after_update` AFTER UPDATE ON `lots` FOR EACH ROW BEGIN
    IF OLD.status != NEW.status THEN
        IF OLD.status = 'available' AND NEW.status IN ('reserved', 'sold') THEN
            UPDATE projects SET available_lots = available_lots - 1 WHERE id = NEW.project_id;
        ELSEIF OLD.status IN ('reserved', 'sold') AND NEW.status = 'available' THEN
            UPDATE projects SET available_lots = available_lots + 1 WHERE id = NEW.project_id;
        END IF;
    END IF;
END
$$
DELIMITER ;

