(2, 0, 'Pack 400', 'pack-400', 400.00, 0.00, '1719687218_fb4b53d10174ca6e44aa.png', 350.00, 300.00, '<ul>\r\n<li>3 Productos a elecci&oacute;n</li>\r\n<li>Plan de acci&oacute;n</li>\r\n<li>C&oacute;digo de &Eacute;tica</li>\r\n<li>Acceso al Backoffice</li>\r\n<li><span class=\"TextRun SCXW3247740 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW3247740 BCX0\"><span class=\"EOP SCXW127418931 BCX0\" data-ccp-props=\"{\"><span class=\"TextRun SCXW160784913 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW160784913 BCX0\">Descuento en todos</span></span><span class=\"EOP SCXW160784913 BCX0\" data-ccp-props=\"{\"> nuestros productos</span></span></span></span></li>\r\n<li><span class=\"TextRun SCXW3247740 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW3247740 BCX0\"><span class=\"EOP SCXW127418931 BCX0\" data-ccp-props=\"{\"><span class=\"EOP SCXW160784913 BCX0\" data-ccp-props=\"{\"><span class=\"TextRun SCXW155963954 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW155963954 BCX0\">Acceso al plan de ganancia</span></span></span></span></span></span></li>\r\n</ul>', '0', NULL, '1', '2023-08-01 22:44:24', NULL),
(3, 0, 'PACK 800', 'pack-800', 800.00, 0.00, '1719687242_bbad29473f1ad8aa3798.png', 750.00, 500.00, '<ul>\r\n<li>5 Productos a elecci&oacute;n</li>\r\n<li>Plan de acci&oacute;n</li>\r\n<li>C&oacute;digo de &Eacute;tica</li>\r\n<li>Acceso al Backoffice</li>\r\n<li><span class=\"TextRun SCXW3247740 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW3247740 BCX0\"><span class=\"EOP SCXW127418931 BCX0\" data-ccp-props=\"{\"><span class=\"TextRun SCXW160784913 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW160784913 BCX0\">Descuento en todos</span></span><span class=\"EOP SCXW160784913 BCX0\" data-ccp-props=\"{\"> nuestros productos</span></span></span></span></li>\r\n<li><span class=\"TextRun SCXW3247740 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW3247740 BCX0\"><span class=\"EOP SCXW127418931 BCX0\" data-ccp-props=\"{\"><span class=\"EOP SCXW160784913 BCX0\" data-ccp-props=\"{\"><span class=\"TextRun SCXW155963954 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW155963954 BCX0\">Acceso al plan de ganancia</span></span></span></span></span></span></li>\r\n</ul>', '0', NULL, '0', '2023-08-01 22:46:42', NULL),
(4, 0, 'PACK 1600', 'pack-1600', 1600.00, 0.00, '1753817550_39fbbbd0dc15b1a42445.png', 1250.00, 1000.00, '<ul>\r\n<li>12 Productos a elecci&oacute;n</li>\r\n<li>Plan de acci&oacute;n</li>\r\n<li>C&oacute;digo de &Eacute;tica</li>\r\n<li>Acceso al Backoffice</li>\r\n<li><span class=\"TextRun SCXW3247740 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW3247740 BCX0\"><span class=\"EOP SCXW127418931 BCX0\" data-ccp-props=\"{\"><span class=\"TextRun SCXW160784913 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW160784913 BCX0\">Descuento en todos</span></span><span class=\"EOP SCXW160784913 BCX0\" data-ccp-props=\"{\"> nuestros productos</span></span></span></span></li>\r\n<li><span class=\"TextRun SCXW3247740 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW3247740 BCX0\"><span class=\"EOP SCXW127418931 BCX0\" data-ccp-props=\"{\"><span class=\"EOP SCXW160784913 BCX0\" data-ccp-props=\"{\"><span class=\"TextRun SCXW155963954 BCX0\" lang=\"ES-PE\" xml:lang=\"ES-PE\" data-contrast=\"auto\"><span class=\"NormalTextRun SCXW155963954 BCX0\">Acceso al plan de ganancia</span></span></span></span></span></span></li>\r\n</ul>', '0', NULL, '1', '2023-08-01 22:48:33', NULL),
(15, 0, 'COFFEE BLUEBERRY', 'coffee-blueberry', 110.00, 30.00, '1752783338_907223eb786a87a86eb9.jpg', 160.00, 100.00, '<div><strong>THERMOGEN</strong>&nbsp; -&nbsp;</div>\r\n<div>\"Activa Tu D&iacute;a\"</div>\r\n<div>&nbsp;</div>\r\n<div><strong>CAF&Eacute; SOLUBLE LIOFILIZADO</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<ul>\r\n<li>Contiene antioxidantes, como polifenoles, que ayudan a combatir el da&ntilde;o causado por los radicales libres.</li>\r\n<li>Estimulante natural, aumenta la alerta mental.</li>\r\n<li>Mejora la concentraci&oacute;n y el rendimiento f&iacute;sico durante los ejercicios.</li>\r\n<li>Reduce el riesgo de enfermedades de p&aacute;rkinson, diabetes tipo 2 y ciertos tipos de c&aacute;ncer.</li>\r\n<li>Efecto positivo en el estado de animo al estimular la liberaci&oacute;n de neurotransmisores como la dopamina y la serotonina.</li>\r\n<li>Estimula la digesti&oacute;n y alivia la sensaci&oacute;n de pesadez despu&eacute;s de una comida.</li>\r\n<li>Contiene vitaminas B2, B3, B5, esenciales &bull;para el metabolismo energ&eacute;tico.</li>\r\n</ul>\r\n<div>Tambi&eacute;n contiene minerales como el potasio, magnesio y fosforo, beneficioso para la salud muscular y &oacute;sea.</div>\r\n<div>&nbsp;</div>\r\n<div><strong>ARANDANOS ROJOS (CRANBERRY)</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<ul>\r\n<li>Previene las infecciones urinarias, contiene proantocianidinas, que impiden que las bacterias se adhieran al tracto urinario.</li>\r\n<li>Rica en antioxidantes, protegen a las c&eacute;lulas del da&ntilde;o causado por los radicales libres.</li>\r\n<li>Ayuda a prevenir las caries dentales.</li>\r\n<li>Mejora la memoria y protege el cerebro del da&ntilde;o causado por los radicales libres.</li>\r\n<li>Mejora la salud ocular, la visi&oacute;n nocturna y protege los ojos del da&ntilde;o causado por la luz de las pantallas electr&oacute;nicas.</li>\r\n<li>Mejora la salud del coraz&oacute;n al reducir los niveles de colesterol malo.</li>\r\n<li>Adecuado para la salud digestiva.</li>\r\n<li>Por su alto contenido en vitamina C puede fortalecer el sistema inmunol&oacute;gico.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>LIMON</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Excelente fuente de vitamina C.</li>\r\n<li>Mejora la funci&oacute;n inmunol&oacute;gica y promueve la producci&oacute;n de col&aacute;geno para una piel saludable.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico por su contenido de vitamina C.</li>\r\n<li>Contiene flavonoides que tienen efectos antioxidantes.</li>\r\n<li>Mejora la digesti&oacute;n, estimula la producci&oacute;n de &aacute;cido g&aacute;strico.</li>\r\n<li>Tiene propiedades diur&eacute;ticas que pueden ayudar desintoxicar el cuerpo.</li>\r\n<li>Mejora la funci&oacute;n renal.</li>\r\n<li>Reducen el riesgo de enfermedades cardiacas.</li>\r\n<li>Esencial para la hidrataci&oacute;n y el funcionamiento optimo del cuerpo.</li>\r\n<li>Promueve la producci&oacute;n de col&aacute;geno y reduce los signos de envejecimiento.</li>\r\n<li>Ayuda a mantener la saciedad y reduce el consumo de calor&iacute;as, lo que puede ser &uacute;til para el control de peso.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>GINSENG SIBERIANO (Eleutherococcus Senticosus)&nbsp;</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Mejora de la energ&iacute;a y reducci&oacute;n de la fatiga, ayudando a mejorar la resistencia f&iacute;sica y mental.</li>\r\n<li>Propiedades adaptogenas, ayuda al cuerpo a adoptarse al stress y mantener el equilibrio.</li>\r\n<li>Estimula el sistema inmunol&oacute;gico, aumentando la producci&oacute;n de c&eacute;lulas inmunitarias.</li>\r\n<li>Beneficioso para el rendimiento acad&eacute;mico y laboral.</li>\r\n<li>Mejora la circulaci&oacute;n, contribuyendo a una mejor salud cardiovascular.</li>\r\n<li>&Uacute;til para las personas que experimentan desequilibrios hormonales debido al stress.</li>\r\n<li>Mejora la salud mental, reduce s&iacute;ntomas de ansiedad.</li>\r\n<li>Mejora la recuperaci&oacute;n despu&eacute;s de los ejercicios.</li>\r\n<li>Beneficioso para personas con diabetes o resistencia a la insulina, porque regula el az&uacute;car en la sangre.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>U&Ntilde;A DE GATO (Uncaria tomentosa)</strong></div>\r\n<div>BENFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>&Uacute;til para el tratamiento de afecciones inflamatorias cr&oacute;nicas como artritis y otras enfermedades inflamatorias.</li>\r\n<li>Aumenta la actividad de gl&oacute;bulos blancos, mejorando la respuesta inmunitaria.</li>\r\n<li>Contiene propiedades antioxidantes, y reduce los riesgos de enfermedades cr&oacute;nicas y el envejecimiento prematuro.</li>\r\n<li>Trata problemas digestivos como la gastritis, las ulceras y el s&iacute;ndrome del intestino irritable.</li>\r\n<li>Contiene propiedades antivirales y antibacteriana.</li>\r\n<li>Tiene propiedades anticancer&iacute;genas ayudando a inhibir el crecimiento de c&eacute;lulas cancerosas.</li>\r\n<li>Ayuda a reducir la presi&oacute;n arterial al dilatar los vasos sangu&iacute;neos y mejora la circulaci&oacute;n cardiovascular.</li>\r\n<li>Alivia el dolor, debido a sus propiedades antiinflamatorias y analg&eacute;sicas.</li>\r\n<li>Mejora la salud articular y reduce el dolor.</li>\r\n<li>Ayuda a desentoxicar el cuerpo, mejorara la funci&oacute;n hep&aacute;tica y renal, facilitando la eliminaci&oacute;n de toxinas.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>ALOE VERA</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Excelente humectante para la piel, mantiene hidratada la piel seca.</li>\r\n<li>Tiene propiedades antiinflamatorias, que pueden ayudar a reducir la hinchaz&oacute;n y el enrojecimiento de la piel contra las afecciones de eccema y psoriasis.</li>\r\n<li>Efecto refrescante que puede ayudar a calmar la piel irritada o quemada por el sol.</li>\r\n<li>Depurativo, elimina toxinas.</li>\r\n<li>Alivia el estre&ntilde;imiento al aumentar la motilidad intestinal.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n<li>Antis&eacute;ptico, ayuda a prevenir la infecci&oacute;n.</li>\r\n<li>Antioxidante que ayuda a proteger las c&eacute;lulas del da&ntilde;o causado por los radicales libres.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>INULINA DE AGAVE</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Mejora la salud digestiva, act&uacute;a como prebi&oacute;tico.</li>\r\n<li>Controla el az&uacute;car en la sangre.</li>\r\n<li>&bull;Controla el apetito y reduciendo la ingesta de cal&oacute;rica.</li>\r\n<li>Mejora la absorci&oacute;n de minerales, como el calcio y el magnesio, que puede contribuir la salud &oacute;sea.</li>\r\n<li>Ayuda a reducir los niveles de colesterol malo en la sangre.</li>\r\n<li>Rico en antioxidantes.</li>\r\n<li>Mejora la salud intestinal y mejora el sistema inmunol&oacute;gico.</li>\r\n<li>Mejora la salud de la piel, ayudando a reducir la inflamaci&oacute;n.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>L &ndash; CARNITINA</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Mejora del metabolismo.</li>\r\n<li>Beneficioso para personas activas.</li>\r\n<li>Mejora la recuperaci&oacute;n despu&eacute;s del ejercicio, ayuda a reducir el dolor muscular.</li>\r\n<li>Reduce los niveles de triglic&eacute;ridos y mejora el perfil del colesterol.</li>\r\n<li>Beneficioso para la salud cerebral a largo plazo y para personas mayores con riesgo de enfermedades neurodegenerativas.</li>\r\n<li>Reduce la fatiga cr&oacute;nica y la sensaci&oacute;n de cansancio.</li>\r\n<li>&Uacute;til para personas con diabetes tipo 2 o resistencia ala insulina.</li>\r\n<li>Apoya a la fertilidad masculina.</li>\r\n<li>Reduce el Stress oxidativo.</li>\r\n<li>Mejora la salud hep&aacute;tica y renal.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>CROMO (Picolinato de cromo)</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Ayuda a mejorar la acci&oacute;n de la insulina.</li>\r\n<li>Regulaci&oacute;n de la glucosa en la sangre.</li>\r\n<li>Controla el apetito y los antojos.</li>\r\n<li>Mejora del metabolismo.</li>\r\n<li>Reduce el colesterol malo LDL y aumentando el colesterol bueno HDL.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div><strong>FRUTO DEL MONJE (LUO HAN GUO)</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Edulcorante sin calor&iacute;as.</li>\r\n<li>Ideal para personas diab&eacute;ticas.</li>\r\n<li>Contiene propiedades antiinflamatorias y antimicrobianas.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n<li>Alivia problemas respiratorio e infecci&oacute;n de garganta.</li>\r\n<li>Reduce riesgos de enfermedades del coraz&oacute;n.</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>\r\n<div><strong>STEVIA</strong></div>\r\n<div>BENEFICIOS:</div>\r\n<div>&nbsp;</div>\r\n<ul>\r\n<li>Edulcorante sin calor&iacute;as.</li>\r\n<li>Bajo en &iacute;ndice gluc&eacute;mico.</li>\r\n<li>Protege a las c&eacute;lulas del da&ntilde;o oxidativo.</li>\r\n<li>Promueve la salud cardiovascular.</li>\r\n<li>Promueve un equilibrio saludable en la flora intestinal.</li>\r\n<li>Seguridad y naturalidad frente a un edulcorante artificial.</li>\r\n<li>Contiene propiedades antimicrobianas &bull;ayudando a combatir ciertos pat&oacute;genos en el cuerpo.&nbsp;</li>\r\n<li>Facilita en el control de p&eacute;rdida de peso.</li>\r\n</ul>', '1', '2', '1', '2024-03-21 23:07:37', NULL),
(17, 0, 'COLLA GEN PLUS Q10', 'colla-gen-plus-q10', 110.00, 30.00, '1723163428_3df8bfe1b207743cb925.jpg', 160.00, 100.00, '<p><strong>Tu Aliado Articular y Cut&aacute;neo +Q10</strong></p>\r\n<p>\"Belleza y Salud Desde el Interior \"</p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Mejora la elasticidad e hidrataci&oacute;n de la piel.</li>\r\n<li>Reduce las arrugas y l&iacute;neas de expresi&oacute;n.</li>\r\n<li>Alivia el dolor articular, y mejora la funci&oacute;n de las articulaciones en personas con artritis y osteoporosis.</li>\r\n<li>El col&aacute;geno hidrolizado puede estimular la producci&oacute;n de col&aacute;geno del cuerpo.</li>\r\n<li>Protege y repara el cart&iacute;lago de las articulaciones.</li>\r\n<li>Previene la perdida &oacute;sea.</li>\r\n<li>Aumenta la masa muscular, especialmente cuando se combina con ejercicios de fuerza.</li>\r\n<li>Mejora la salud intestinal al aumentar la producci&oacute;n la producci&oacute;n de mucina, sustancia que protege el revestimiento intestinal.</li>\r\n<li>Fortalece las u&ntilde;as y el cabello, haciendo menos propenso a romperse y quebrarse.</li>\r\n</ul>\r\n<p><strong>CAMU CAMU</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Alto en ANTOCIANINAS, pigmentos con propiedades antioxidantes.</li>\r\n<li>Contiene POLIFENOLES, con antioxidantes y antiinflamatorias que reducen enfermedades cr&oacute;nicas.</li>\r\n<li>Compuesto de propiedades anticancer&iacute;genas.</li>\r\n<li>Contiene minerales como: calcio, potasio, fosforo.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico, por la vitamina C, que protege al cuerpo de enfermedades.</li>\r\n<li>Reduce la inflamaci&oacute;n en el cuerpo, lo que puede ser beneficioso para la artritis y para la inflamaci&oacute;n intestinal.</li>\r\n<li>Mejora la salud de la piel por la vitamina C.</li>\r\n<li>Protege la salud de los ojos. Cataratas y la degeneraci&oacute;n macular.</li>\r\n<li>Fortalece los huesos y dientes.</li>\r\n</ul>\r\n<p><strong>ARANDANOS ROJOS (CRANBERRY)</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Previene las infecciones urinarias, contiene proantocianidinas, que impiden que las bacterias se adhieran al tracto urinario.</li>\r\n<li>Rica en antioxidantes, protegen a las c&eacute;lulas del da&ntilde;o causado por los radicales libres.</li>\r\n<li>Ayuda a prevenir las caries dentales.</li>\r\n<li>Mejora la memoria y protege el cerebro del da&ntilde;o causado por los radicales libres.</li>\r\n<li>Mejora la salud ocular, la visi&oacute;n nocturna y protege los ojos</li>\r\n</ul>\r\n<p>del da&ntilde;o causado por la luz de las pantallas electr&oacute;nicas.</p>\r\n<ul>\r\n<li>Mejora la salud del coraz&oacute;n al reducir los niveles de colesterol bueno.</li>\r\n<li>Adecuado para la salud digestiva.</li>\r\n<li>Por su alto contenido en vitamina C puede fortalecer el sistema inmunologico.</li>\r\n</ul>\r\n<p><strong>BIOTINA (conocida como la vitamina B7 o H)</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Fortalece la ca&iacute;da del cabello y u&ntilde;as.</li>\r\n<li>Mejora la salud de la piel, al mantener la hidrataci&oacute;n y la elasticidad.</li>\r\n<li>Ayuda a convertir los alimentos en energ&iacute;a.</li>\r\n<li>Mejora la sensibilidad a la insulina y a regular los niveles de az&uacute;car en la sangre, diabetes tipo2.</li>\r\n<li>Mejora la funci&oacute;n cognitiva, la memoria y la funci&oacute;n cerebral.</li>\r\n<li>Recomendable para embarazadas, suplemento prenatal.</li>\r\n</ul>\r\n<p><strong>CARTILAGO DE TIBURON</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Alivia dolores articulares.</li>\r\n<li>Mejora la elasticidad e hidrataci&oacute;n de la piel.</li>\r\n<li>Fortalecimiento del sistema inmunol&oacute;gico.</li>\r\n<li>El cart&iacute;lago de tibur&oacute;n es rico en col&aacute;geno.</li>\r\n<li>Contiene minerales como: calcio, fosforo, magnesio, potasio, sodio, cloro, hierro, zinc, cobre y manganeso.</li>\r\n<li>El col&aacute;geno de tibur&oacute;n contiene GLUCOSAMINA Y CONDROITINA.</li>\r\n</ul>\r\n<p><strong>COENZIMA Q1O (conocida UBIQUINONA)</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Reduce el riesgo de enfermedades cardiacas, como insuficiencia cardiaca congestiva y la angina de pecho.</li>\r\n<li>Mejora del rendimiento f&iacute;sico al aumentar la energ&iacute;a y reducir la fatiga.</li>\r\n<li>Protege contra las enfermedades neurodegenerativas, ALZEIMER Y PARKINSON.</li>\r\n<li>Mejora la funci&oacute;n cognitiva en personas mayores.</li>\r\n<li>Mejora la calidad del esperma en hombres inf&eacute;rtiles.</li>\r\n<li>Beneficios reduce la presi&oacute;n arterial, protege contra el c&aacute;ncer, mejora la salud de la piel y reduce el dolor articular.</li>\r\n</ul>\r\n<p><strong>GLUCOSAMINA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Alivia el dolor articular asociado con la osteoartritis.</li>\r\n<li>Efectiva como los medicamentos antiinflamatorios, no contiene asteroides, para reducir el dolor.</li>\r\n<li>Mejora la flexibilidad y la movilidad de las articulaciones.</li>\r\n<li>Reduce la inflamaci&oacute;n por sus propiedades antiinflamatorias.</li>\r\n<li>Protege el cart&iacute;lago del da&ntilde;o y la degeneraci&oacute;n.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico, mejora la salud de la piel.</li>\r\n<li>Puede acelerar la cicatrizaci&oacute;n de heridas.</li>\r\n</ul>\r\n<p><strong>CALCIO</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Formaci&oacute;n y mantenimiento de huesos y dientes.</li>\r\n<li>Funci&oacute;n muscular y nerviosa, ayuda a los m&uacute;sculos a contraerse y relajarse, y a las neuronas a enviar y recibir mensajes.</li>\r\n<li>Factor esencial en la coagulaci&oacute;n de la sangre.</li>\r\n<li>Importante en la liberaci&oacute;n de hormonas y neurotransmisores, como la insulina, el glucag&oacute;n y la serotonina.</li>\r\n<li>Regula la presi&oacute;n arterial y dilata los vasos sangu&iacute;neos.</li>\r\n<li>Reduce el riesgo de c&aacute;ncer, mejora la salud cardiovascular.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n</ul>\r\n<p><strong>ALOE VERA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Excelente humectante para la piel, mantiene hidratada la piel seca.</li>\r\n<li>Tiene propiedades antiinflamatorias, que pueden ayudar a reducir la hinchaz&oacute;n y el enrojecimiento de la piel contra las afecciones de eccema y psoriasis.</li>\r\n<li>Efecto refrescante que puede ayudar a calmar la piel irritada o quemada por el sol.</li>\r\n<li>Depurativo, elimina toxinas.</li>\r\n<li>Alivia el estre&ntilde;imiento al aumentar la motilidad intestinal.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n<li>Antis&eacute;ptico, ayuda a prevenir la infecci&oacute;n.</li>\r\n<li>Antioxidante que ayuda a proteger las c&eacute;lulas del da&ntilde;o causado por los radicales libres.</li>\r\n</ul>\r\n<p><strong>ZINC</strong></p>\r\n<p>BENEFICIOS</p>\r\n<ul>\r\n<li>Esencial para el desarrollo y la funci&oacute;n de las c&eacute;lulas inmunitarias.</li>\r\n<li>Prote&iacute;na importante para la cicatrizaci&oacute;n de heridas.</li>\r\n<li>Importante para el crecimiento y desarrollo normal de ni&ntilde;os y adolescentes.</li>\r\n<li>Importante para el embarazo y la lactancia.</li>\r\n<li>Necesario para la producci&oacute;n de hormonas sexuales y la funci&oacute;n reproductiva tanto en hombres y mujeres.</li>\r\n<li>Necesario para el funcionamiento normal del gusto y el olfato.</li>\r\n<li>Ayuda a mejorar el rendimiento deportivo.</li>\r\n<li>Protege la piel del da&ntilde;o solar.</li>\r\n</ul>\r\n<p><strong>FRUTO DEL MONJE (LUO HAN GUO)</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Edulcorante sin calor&iacute;as.</li>\r\n<li>Ideal para personas diab&eacute;ticas.</li>\r\n<li>Contiene propiedades antiinflamatorias y antimicrobianas.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n<li>Alivia problemas respiratorio e infecci&oacute;n de garganta.</li>\r\n<li>Reduce riesgos de enfermedades del coraz&oacute;n.</li>\r\n</ul>\r\n<p><strong>YACON</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Excelente para personas con diabetes.</li>\r\n<li>Promueve la salud digestiva.</li>\r\n<li>Ayuda en el control de peso.</li>\r\n<li>Combate los radicales libres, protegiendo a las c&eacute;lulas del da&ntilde;o oxidativo.</li>\r\n<li>Regula la presi&oacute;n y la salud &oacute;sea.</li>\r\n<li>Contiene propiedades antiinflamatorias.</li>\r\n<li>Mejora el metabolismo.</li>\r\n</ul>\r\n<p><strong>STEVIA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Edulcorante sin calor&iacute;as.</li>\r\n<li>Bajo en &iacute;ndice gluc&eacute;mico.</li>\r\n<li>Protege a las c&eacute;lulas del da&ntilde;o oxidativo.</li>\r\n<li>Promueve la salud cardiovascular.</li>\r\n<li>Promueve un equilibrio saludable en la flora intestinal.</li>\r\n<li>Seguridad y naturalidad frente a un edulcorante artificial.</li>\r\n<li>Contiene propiedades antimicrobianas ayudando a combatir ciertos pat&oacute;genos en el cuerpo. Facilita en el control de p&eacute;rdida&nbsp;de&nbsp;peso.</li>\r\n</ul>', '1', '2', '1', '2024-03-21 23:17:49', NULL),
(18, 0, 'ENERGY LIFE', 'energy-life', 110.00, 30.00, '1723163440_7b14d9fbe19c7c2c6df9.jpg', 160.00, 100.00, '<p><strong>Rendimiento F&iacute;sico y Mental</strong></p>\r\n<p>\"La chispa que enciende tu d&iacute;a\"</p>\r\n<p>&nbsp;</p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Rica en nutrientes, excelente fuente de vitaminas A y C.</li>\r\n<li>Contiene antioxidantes como polifenoles y los carotenoides.</li>\r\n<li>Mejora la digesti&oacute;n gracias a la fibra diet&eacute;tica presente en el maracuy&aacute;.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n<li>Contribuye a una mejor salud cardiovascular.</li>\r\n<li>Beneficioso para la salud ocular, previene cataratas y degeneraci&oacute;n macular.</li>\r\n<li>Contiene propiedades antiinflamatorias gracias a los flavonoides.</li>\r\n<li>Esencial para mantener huesos y dientes fuertes y saludables.</li>\r\n<li>Contiene propiedades sedantes leves, lo que puede reducir la ansiedad y promover un mejor sue&ntilde;o.</li>\r\n<li>Contiene antioxidantes y vitamina C, promueve la producci&oacute;n de col&aacute;geno.</li>\r\n<li>Protege loa rayos UV y otros factores ambientales.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>AGUYMANTO</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Contine altos niveles de antioxidantes como los polifenoles y carotenoides que ayudan a combatir el da&ntilde;o de los radicales libre.</li>\r\n<li>Fuente de vitaminas y minerales. Fuente de vitaminas A, C y del complejo B, (especialmente B1, B2 y B3) minerales como: hierro, fosforo y potasio.</li>\r\n<li>Propiedades antiinflamatorio.</li>\r\n<li>Refuerza el sistema inmunol&oacute;gico.</li>\r\n<li>Beneficios digestivos por la fibra diet&eacute;tica.</li>\r\n<li>Control del az&uacute;car en la sangre.</li>\r\n<li>Contiene propiedades diur&eacute;ticas, ayuda a eliminar el exceso de l&iacute;quidos y toxinas.</li>\r\n<li>Salud ocular.</li>\r\n<li>Mejora la salud del coraz&oacute;n.</li>\r\n<li>Propiedades anticancer&iacute;genas.</li>\r\n<li>Mejora la salud hep&aacute;tica.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>MANZANA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Rica en nutrientes y antioxidantes.</li>\r\n<li>Promueve la salud digestiva.</li>\r\n<li>Saludable para prevenir el estre&ntilde;imiento y mantener un microbioma equilibrado.</li>\r\n<li>Controla el peso.</li>\r\n<li>Regula el exceso de az&uacute;car en la sangre.</li>\r\n<li>Reduce riesgos de enfermedades cardiovasculares.</li>\r\n<li>Reduce enfermedades neurodegenerativas como el Alzheimer.</li>\r\n<li>Mejora la funci&oacute;n pulmonar y una reducci&oacute;n del riesgo de enfermedades respiratorias como el asma.</li>\r\n<li>Previene la osteoporosis.</li>\r\n<li>Reduce riesgos de caries dentales y enfermedades de las enc&iacute;as.</li>\r\n<li>Mejora el sistema inmunol&oacute;gico.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>GUAYUZA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Estimulante natural, contiene cafe&iacute;na, teobromina y teofilina.</li>\r\n<li>Mejora del enfoque y la concentraci&oacute;n.</li>\r\n<li>Aumenta el metabolismo, lo que puede facilitar la perdida de peso y la quema de grasa.</li>\r\n<li>Protege contra enfermedades cardiovascular.</li>\r\n<li>Regula los niveles de az&uacute;car en la sangre.</li>\r\n<li>Apoya en la digesti&oacute;n.</li>\r\n<li>Desintoxica el cuerpo</li>\r\n<li>Reduce el stress, la ansiedad y mejora el estado de animo.</li>\r\n<li>Promueve un sue&ntilde;o reparador</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>GUARANA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Contiene altas concentraciones de cafe&iacute;na, que act&uacute;a como estimulante del sistema nervioso central.</li>\r\n<li>Mejora la memoria y otras funciones cognitivas</li>\r\n<li>Aumenta el metabolismo, lo que puede facilitar la perdida de peso y la quema de grasas.</li>\r\n<li>Puede suprimir el apetito y aumentar la sensaci&oacute;n de saciedad.</li>\r\n<li>Contiene compuestos antioxidantes como catequinas y taninos que ayudan a combatir el da&ntilde;o de los radicales libres.</li>\r\n<li>Aumenta la resistencia y el rendimiento f&iacute;sico y mental.</li>\r\n<li>Previene la formaci&oacute;n de co&aacute;gulos sangu&iacute;neos.</li>\r\n<li>Contiene efectos gastroprotectores y antiinflamatorios en el tracto gastrointestinal.</li>\r\n<li>Reduce el stress y la ansiedad, algunos estudios sugieren que la cafe&iacute;na del guarana puede tener efectos ansiol&iacute;ticos y antidepresivos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>MACA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Energizante natural, aumenta los niveles de energ&iacute;a.</li>\r\n<li>Combate la fatiga, el stress y la ansiedad.</li>\r\n<li>Mejora la memoria, tiene efectos positivos en la salud mental.</li>\r\n<li>Reguladora hormonal, ayuda equilibrar las hormonas en el cuerpo beneficiosa para la salud en general.</li>\r\n<li>Mejora la fertilidad, tanto en hombres y mujeres.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>GINSENG SIBERIANO (Eleutherococcus Senticosus)</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Mejora de la energ&iacute;a y reducci&oacute;n de la fatiga, ayudando a mejorar la resistencia f&iacute;sica y mental.</li>\r\n<li>Propiedades adaptogenas, ayuda al cuerpo a adoptarse al stress y mantener el equilibrio.</li>\r\n<li>Estimula el sistema inmunol&oacute;gico, aumentando la producci&oacute;n de c&eacute;lulas inmunitarias.</li>\r\n<li>Beneficioso para el rendimiento acad&eacute;mico y laboral.</li>\r\n<li>Mejora la circulaci&oacute;n, contribuyendo a una mejor salud cardiovascular.</li>\r\n<li>&Uacute;til para las personas que experimentan desequilibrios hormonales debido al stress.</li>\r\n<li>Mejora la salud mental, reduce s&iacute;ntomas de ansiedad.</li>\r\n<li>Mejora la recuperaci&oacute;n despu&eacute;s de los ejercicios.</li>\r\n<li>Beneficioso para personas con diabetes o resistencia a la insulina, porque regula el az&uacute;car en la sangre.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>FRUTO DEL MONJE (LUO HAN GUO)</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Edulcorante sin calor&iacute;as.</li>\r\n<li>Ideal para personas diab&eacute;ticas.</li>\r\n<li>Contiene propiedades antiinflamatorias y antimicrobianas.</li>\r\n<li>Fortalece el sistema inmunol&oacute;gico.</li>\r\n<li>Alivia problemas respiratorio e infecci&oacute;n de garganta.</li>\r\n<li>Reduce riesgos de enfermedades del coraz&oacute;n.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>YACON</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Excelente para personas con diabetes.</li>\r\n<li>Promueve la salud digestiva.</li>\r\n<li>Ayuda en el control de peso.</li>\r\n<li>Combate los radicales libres, protegiendo a las c&eacute;lulas del da&ntilde;o oxidativo.</li>\r\n<li>Regula la presi&oacute;n y la salud &oacute;sea.</li>\r\n<li>Contiene propiedades antiinflamatorias.</li>\r\n<li>Mejora el metabolismo.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>STEVIA</strong></p>\r\n<p>BENEFICIOS:</p>\r\n<ul>\r\n<li>Edulcorante sin calor&iacute;as.</li>\r\n<li>Bajo en &iacute;ndice gluc&eacute;mico.</li>\r\n<li>Protege a las c&eacute;lulas del da&ntilde;o oxidativo.</li>\r\n<li>Promueve la salud cardiovascular.</li>\r\n<li>Promueve un equilibrio saludable en la flora intestinal.</li>\r\n<li>Seguridad y naturalidad frente a un edulcorante artificial.</li>\r\n<li>Contiene propiedades antimicrobianas ayudando a combatir ciertos pat&oacute;genos en el cuerpo. Facilita en el control de p&eacute;rdida de</li>\r\n</ul>', '1', '2', '1', '2024-04-22 20:03:03', NULL),
(19, 0, 'POWER LIFE', 'power-life', 120.00, 29.00, '1750296453_9d0f954938856a6c6127.jpg', 180.00, 110.00, '<p><strong>POWER LIFE</strong></p>\r\n<p><strong>BENEFICIOS</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>MARACUY&Aacute;:</strong></p>\r\n<p>(fruto de la pasion), rico en vitamina C y carotenoides, mejora la salud cardiovascular y fortalece el sistema inmunol&oacute;gico, favorece el sue&ntilde;o, reduce el estr&eacute;s y apoya el equilibrio hormonal masculino, la fibra mejora la digesti&oacute;n y ayuda a controlar el peso, rico en antioxidantes que protegen c&eacute;lulas y apoyan la salud sexual.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>BROMELINA DE PI&Ntilde;A:</strong></p>\r\n<p>Es una enzima que mejora la digesti&oacute;n y reduce la inflamaci&oacute;n en m&uacute;sculos y articulaciones, favorece la recuperaci&oacute;n f&iacute;sica y alivia dolores despu&eacute;s del ejercicio, apoya la salud prost&aacute;tica al combatir procesos inflamatorios, refuerza el sistema inmunol&oacute;gic.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>SAW PALMETTO:</strong></p>\r\n<p>Es una palmera enana, su fruto es utilizado para aliviar los s&iacute;ntomas de la hiperplasia prost&aacute;tica benigna (HPB), contribuye a mejorar el flujo urinario, apoya el equilibrio hormonal al inhibir la conversi&oacute;n de testosterona en DHT, contribuye a mejoras en el libido y la salud sexual.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>ASHWAGANDHA:</strong></p>\r\n<p>Es una planta que contribuye a reducir el estr&eacute;s y la ansiedad al disminuir los niveles de cortisol, aumenta los niveles de testosterona y mejora la fertilidad (calidad del esperma), favorece el crecimiento muscular y la fuerza f&iacute;sica en hombres que entrenan, mejora la energ&iacute;a, el estado de &aacute;nimo y la funci&oacute;n sexual.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>MACA NEGRA<em>:</em></strong></p>\r\n<p>Es una ra&iacute;z, la cual tiene efectos positivos en la energ&iacute;a, fertilidad y rendimiento sexual masculino, aumenta el libido y el deseo sexual de forma natural, mejora la cantidad y movilidad de espermatozoides favoreciendo la fertilidad, incrementa la energ&iacute;a f&iacute;sica y mental, &uacute;til para el rendimiento deportivo, apoya el equilibrio hormonal sin alterar los niveles de testosterona directamente.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>GINKGO BILOBA:</strong></p>\r\n<p>Es una planta con propiedades que ayudan a la circulaci&oacute;n sangu&iacute;nea, favoreciendo la funci&oacute;n er&eacute;ctil y la salud sexual, aumenta la concentraci&oacute;n y la memoria mejorando el rendimiento mental, reduce el estr&eacute;s y la ansiedad gracias a sus efectos calmantes sobre el sistema nervioso, sus propiedades antioxidantes protegen las c&eacute;lulas del da&ntilde;o y el envejecimiento.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>GINSENG:</strong></p>\r\n<p>Es una ra&iacute;z que contribuye a la mejora de la funci&oacute;n er&eacute;ctil y la libido, aumenta la energ&iacute;a f&iacute;sica y mental combatiendo el cansancio y la fatiga, estimula el sistema inmunol&oacute;gico y la resistencia al estr&eacute;s, favorece el rendimiento cognitivo y la concentraci&oacute;n.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>ACHIOTE:</strong></p>\r\n<p>Es una planta tropical, cuyas semillas contienen propiedades antioxidantes gracias a los carotenoides (como la bixina), que protegen las c&eacute;lulas del da&ntilde;o oxidativo, protecci&oacute;n prost&aacute;tica aliviando inflamaciones de la pr&oacute;stata y del tracto urinario, mejora de la salud digestiva y potencial afrodis&iacute;aco.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>HUANARPO MACHO:</strong></p>\r\n<p>Es una planta que aumenta la libido y mejora el deseo sexual de forma natural, favorece la funci&oacute;n er&eacute;ctil, apoya el equilibrio hormonal masculino estimulando la producci&oacute;n de testosterona y fortalece el sistema reproductivo.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>U&Ntilde;A DE GATO:</strong></p>\r\n<p>Es una planta que fortalece el sistema inmunol&oacute;gico, ayudando a prevenir enfermedades e infecciones, contiene propiedades antiinflamatorias, &uacute;tiles para aliviar dolores articulares y musculares, mejora la salud prost&aacute;tica al reducir la inflamaci&oacute;n y promover la salud del tracto urinario, aumenta la energ&iacute;a y vitalidad contribuyendo al bienestar general y la recuperaci&oacute;n f&iacute;sica.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>MASHUA NEGRA:</strong></p>\r\n<p>Mejora la fertilidad masculina y la funci&oacute;n sexual, propiedades afrodis&iacute;acas. aumenta la energ&iacute;a y la resistencia f&iacute;sica siendo beneficiosa para la salud en general, apoya la salud prost&aacute;tica y el bienestar urinario.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>VITAMINAS C, B1, B3, B9:</strong></p>\r\n<p>Son esenciales para la salud masculina, fortaleciendo el sistema inmunol&oacute;gico, mejorando la circulaci&oacute;n y la salud cardiovascular, la vitamina C favorece la regeneraci&oacute;n celular, la B1 aumenta la energ&iacute;a y la funci&oacute;n nerviosa, la B3 mejora el colesterol y la circulaci&oacute;n, y la B9 apoya la salud reproductiva y reduce riesgos cardiovasculares.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>ZINC</strong>:</p>\r\n<p>Es un mineral esencial para la salud masculina, fundamental en la producci&oacute;n de testosterona y la funci&oacute;n inmune, ayuda en la fertilidad masculina mejorando la calidad del esperma y el conteo de espermatozoides, tiene propiedades antioxidantes.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>FRUTO DEL MONJE</strong>:</p>\r\n<p>Edulcorante natural bajo en calor&iacute;as y no eleva los niveles de az&uacute;car en sangre, ideal para personas con diabetes, contiene antioxidantes que ayudan a combatir el envejecimiento celular y promueven la salud respiratoria.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>STEVIA</strong>:</p>\r\n<p>Planta con sabor dulce sin aportar calor&iacute;as, es un edulcorante natural que no eleva los niveles de glucosa en sangre, excelente opci&oacute;n para personas con diabete, propiedades antioxidantes que protegen las c&eacute;lulas del da&ntilde;o y pu</p>\r\n<p>eden ayudar a reducir la presi&oacute;n arterial.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>---</p>', '1', '2', '1', '2025-05-08 17:36:28', NULL),
(20, 0, 'TÉ LIFE ', 'te-life-', 125.00, 30.00, '1752783870_64659e073539fa7dca04.jpg', 195.00, 60.00, '<p><strong>T&Eacute; Life</strong> -</p>\r\n<p>Thermogen Natural (<strong>Control de Peso</strong>)</p>\r\n<p><strong>Activa tu metabolismo,</strong></p>\r\n<p><strong>equilibra tu digesti&oacute;n y vive m&aacute;s ligero.</strong></p>\r\n<p>&nbsp;</p>\r\n<p>✅ <strong>Beneficios</strong></p>\r\n<p><strong>Acelera el metabolismo y promueve la quema de grasa</strong></p>\r\n<p>&gt; Gracias a la combinaci&oacute;n de t&eacute; verde, t&eacute; negro, caf&eacute; verde y caf&eacute; negro, que aportan cafe&iacute;na natural y antioxidantes termog&eacute;nicos que estimulan el gasto energ&eacute;tico y la oxidaci&oacute;n de grasas.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Apoya la desintoxicaci&oacute;n y la depuraci&oacute;n del cuerpo</strong></p>\r\n<p>&gt; El t&eacute; rojo, el tamarindo y el poderoso Amalaki ayudan a eliminar toxinas, mejorar la digesti&oacute;n y reducir la retenci&oacute;n de l&iacute;quidos de forma natural.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Controla el apetito y mejora la salud digestiva</strong></p>\r\n<p>&gt; La inulina de agave y el &aacute;loe vera liofilizado aportan fibra prebi&oacute;tica, favoreciendo la saciedad, el equilibrio intestinal y la absorci&oacute;n de nutrientes.</p>\r\n<p><strong>Endulzado naturalmente, sin calor&iacute;as</strong></p>\r\n<p>&gt; Contiene fruto del monje y stevia, edulcorantes naturales sin az&uacute;car, ideales para personas que cuidan su peso y su salud metab&oacute;lica.</p>', '1', '2', '1', '2025-07-17 20:24:30', NULL),
(21, 0, 'ENERGY GOJI', 'energy-goji', 110.00, 29.00, '1752784480_9cd5e7580becadfc937e.jpg', 160.00, 50.00, '<p>&nbsp;</p>\r\n<p><strong>ENERGY GOJI: </strong></p>\r\n<p><strong>Energ&iacute;a que fluye, salud que perdura</strong>.</p>\r\n<p>Energizante 100% Natural&nbsp;</p>\r\n<p><strong>F&oacute;rmula avanzada con frutas selectas, adapt&oacute;genos y vitaminas que activan tu cuerpo y mente de forma saludable.</strong></p>\r\n<p>&nbsp;</p>\r\n<p>✅ <strong>Beneficios Principales</strong>:</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Energ&iacute;a natural y duradera</strong>:</p>\r\n<p>Con guaran&aacute;, guayusa y ginseng, ayuda a mantener la energ&iacute;a f&iacute;sica y mental durante el d&iacute;a, sin efectos colaterales ni sobrecargas al sistema nervioso.</p>\r\n<p><strong>Mayor concentraci&oacute;n y claridad mental:</strong></p>\r\n<p>El ginseng y las vitaminas B6 y B12 apoyan la funci&oacute;n cognitiva, el enfoque y el estado de &aacute;nimo, ideales para jornadas exigentes.</p>\r\n<p><strong>Activa el metabolismo de forma saludable</strong>:</p>\r\n<p>La combinaci&oacute;n de goji, moringa y lim&oacute;n promueve el equilibrio metab&oacute;lico y favorece procesos naturales como la termog&eacute;nesis y la quema de grasa.</p>\r\n<p><strong>Rico en antioxidantes y vitamina C:</strong></p>\r\n<p>Gracias a frutas como naranja, mandarina y lim&oacute;n, fortalece el sistema inmunol&oacute;gico, combate el estr&eacute;s oxidativo y protege las c&eacute;lulas.</p>\r\n<p><strong>Apoyo inmunol&oacute;gico integral:</strong></p>\r\n<p>El goji y la moringa contienen nutrientes esenciales que fortalecen tus defensas, ayudando al organismo a resistir enfermedades y fatiga.</p>\r\n<p><strong>Sin az&uacute;car, sin qu&iacute;micos, 100% natural:</strong></p>\r\n<p>Endulzado con fruto del monje y stevia, es apto para diab&eacute;ticos, personas en control de peso, y quienes buscan un estilo de vida saludable.</p>', '1', '2', '1', '2025-07-17 20:34:09', NULL);

