--
-- Structure for view `view_available_lots`
--
DROP TABLE IF EXISTS `view_available_lots`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_available_lots`  AS SELECT `l`.`id` AS `id`, `l`.`lot_number` AS `lot_number`, `l`.`block` AS `block`, `l`.`area_sqm` AS `area_sqm`, `l`.`current_price` AS `current_price`, `l`.`status` AS `status`, `p`.`name` AS `project_name`, `p`.`location` AS `location`, `p`.`code` AS `project_code`, round(`l`.`current_price` / `l`.`area_sqm`,2) AS `price_per_sqm` FROM (`lots` `l` join `projects` `p` on(`l`.`project_id` = `p`.`id`)) WHERE `l`.`status` = 'available' AND `p`.`status` = 'active' ;

