-- Structure for view `view_customer_properties`
--
DROP TABLE IF EXISTS `view_customer_properties`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_customer_properties`  AS SELECT `c`.`id` AS `customer_id`, `c`.`name` AS `customer_name`, `c`.`lastname` AS `customer_lastname`, `c`.`email` AS `email`, `c`.`phone` AS `phone`, `l`.`id` AS `lot_id`, `l`.`lot_number` AS `lot_number`, `l`.`block` AS `block`, `l`.`area_sqm` AS `area_sqm`, `l`.`current_price` AS `current_price`, `l`.`status` AS `lot_status`, `p`.`name` AS `project_name`, `p`.`location` AS `location`, `ct`.`contract_number` AS `contract_number`, `ct`.`monthly_payment` AS `monthly_payment`, `ct`.`status` AS `contract_status` FROM (((`customers` `c` join `lots` `l` on(`c`.`id` = `l`.`customer_id`)) join `projects` `p` on(`l`.`project_id` = `p`.`id`)) left join `contracts` `ct` on(`l`.`id` = `ct`.`lot_id`)) ;

